function parseAIOutput(nodeName) {
  const raw = $(nodeName).first().json.output;

  if (!raw) {
    return {};
  }

  try {
    // Remove markdown code fences if the AI added them
    const cleaned = raw
      .replace(/```json/gi, "")
      .replace(/```/g, "")
      .trim();

    return JSON.parse(cleaned);
  } catch (error) {
    return {
      parsing_error: true,
      raw_output: raw
    };
  }
}


